class Solution {
    public long minCost(int cost1, int cost2, int costBoth, int need1, int need2) {
        long m = Math.min(need1, need2), M = Math.max(need1, need2);
        return Math.min(f(0, cost1, cost2, costBoth, need1, need2),
               Math.min(f(m, cost1, cost2, costBoth, need1, need2),
                        f(M, cost1, cost2, costBoth, need1, need2)));
    }
    private long f(long b, int c1, int c2, int cb, int n1, int n2) {
        return b * cb
             + Math.max(0, n1 - b) * c1
             + Math.max(0, n2 - b) * c2;
    }
}

