class Solution:
    def minCost(self, cost1, cost2, costBoth, need1, need2):
        def f(b):
            return (b * costBoth
                    + max(0, need1 - b) * cost1
                    + max(0, need2 - b) * cost2)
        lo, hi = 0, max(need1, need2)
        while hi - lo > 2:
            m1 = lo + (hi - lo) // 3
            m2 = hi - (hi - lo) // 3
            if f(m1) <= f(m2):
                hi = m2
            else:
                lo = m1
        return min(f(b) for b in range(lo, hi + 1))

