class Solution {
    public long minCost(int cost1, int cost2, int costBoth, int need1, int need2) {
        long lo = 0, hi = Math.max(need1, need2);
        while (hi - lo > 2) {
            long m1 = lo + (hi - lo) / 3, m2 = hi - (hi - lo) / 3;
            if (f(m1, cost1, cost2, costBoth, need1, need2)
                    <= f(m2, cost1, cost2, costBoth, need1, need2)) hi = m2;
            else lo = m1;
        }
        long ans = Long.MAX_VALUE;
        for (long b = lo; b <= hi; b++)
            ans = Math.min(ans, f(b, cost1, cost2, costBoth, need1, need2));
        return ans;
    }
    private long f(long b, int c1, int c2, int cb, int n1, int n2) {
        return b * cb + Math.max(0, n1 - b) * c1 + Math.max(0, n2 - b) * c2;
    }
}

